svg.script:


var pantalla = document.getElementById("pantalla");
var valorActual = "0";
var operador = null;
var valorAnterior = null;

function actualizarPantalla() {
  pantalla.textContent = valorActual;
}

function agregarDigito(digito) {
  if (valorActual === "0") {
    valorActual = digito;
  } else {
    valorActual += digito;
  }
  actualizarPantalla();
}

function limpiar() {
  valorActual = "0";
  operador = null;
  valorAnterior = null;
  actualizarPantalla();
}

function setOperador(op) {
  if (operador !== null) {
    calcular();
  }
  valorAnterior = valorActual;
  operador = op;
  valorActual = "0";
}

function calcular() {
  if (operador === null || valorAnterior === null) return;
  var a = parseFloat(valorAnterior);
  var b = parseFloat(valorActual);
  var resultado = 0;

  switch (operador) {
    case "+": resultado = a + b; break;
    case "-": resultado = a - b; break;
    case "*": resultado = a * b; break;
    case "/": resultado = b !== 0 ? a / b : "Error"; break;
  }

  if (resultado === "Error") {
    valorActual = "Error";
  } else {
    valorActual = resultado.toString();
  }
  operador = null;
  valorAnterior = null;
  actualizarPantalla();
}

// Asignar eventos a los números (por clase btn)
var botonesNum = document.querySelectorAll(".btn");
for (var i = 0; i < botonesNum.length; i++) {
  botonesNum[i].addEventListener("click", function() {
    var val = this.getAttribute("data-val");
    if (val) agregarDigito(val);
  });
}

// Botón 0 especial (no tiene clase btn pero sí data-val)
document.getElementById("btn0").addEventListener("click", function() {
  agregarDigito("0");
});

// Botones de operadores
var ops = document.querySelectorAll(".op");
for (var i = 0; i < ops.length; i++) {
  ops[i].addEventListener("click", function() {
    var op = this.getAttribute("data-op");
    setOperador(op);
  });
}

// Botón C (clear)
document.getElementById("btnC").addEventListener("click", limpiar);

// Botón igual
document.getElementById("btnIgual").addEventListener("click", calcular);
